 'fgs_analysis-04':'report-metrics','fgs_analysis-05':'trend','fgs_analysis-06':'trend','fgs_analysis-07':'compare',
 'wing_analysis-01':'report-metrics','wing_analysis-02':'report-comments','wing_analysis-03':'brief',
